@androidx.media3.common.util.UnstableApi
public class ShareShortcutsTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private Activity activity;private boolean complete;private final AtomicReference<String> shareDebug=new AtomicReference<>("");private final List<File> files=new ArrayList<>();
 private Object field(Object owner,String name)throws Exception{Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
 private Uri fixture(String asset,String extension)throws Exception{File dir=new File(c.getCacheDir(),"shares/shortcuts-"+UUID.randomUUID());assertTrue(dir.mkdirs());File f=new File(dir,"Onda share"+extension);files.add(f);try(InputStream in=ins.getContext().getAssets().open(asset);OutputStream out=new FileOutputStream(f)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}return FileProvider.getUriForFile(c,c.getPackageName()+".share",f);}
 @After public void after(){if(!complete&&activity!=null)try{screenshot("share-shortcuts-failure");}catch(Exception ignored){}if(activity!=null){ins.runOnMainSync(()->{try{if(activity instanceof MainActivity){MediaController player=(MediaController)field(activity,"player");if(player!=null){player.stop();player.clearMediaItems();}}}catch(Exception ignored){}activity.finish();});ins.waitForIdleSync();}for(File f:files){f.delete();f.getParentFile().delete();}}
 private interface Check {boolean ready()throws Exception;}
 private void waitFor(Check check)throws Exception{boolean[] ready={false};for(int i=0;i<200;i++){ins.runOnMainSync(()->{try{ready[0]=check.ready();}catch(Exception e){throw new RuntimeException(e);}});if(ready[0])return;Thread.sleep(50);}fail("Shortcut did not become ready");}
 private Button button(View view,String description){if(view instanceof Button&&description.equals(view.getContentDescription()))return (Button)view;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++){Button found=button(group.getChildAt(i),description);if(found!=null)return found;}}return null;}
 private Instrumentation.ActivityMonitor chooser(AtomicReference<Intent> result){Instrumentation.ActivityMonitor monitor=new Instrumentation.ActivityMonitor(){@Override public Instrumentation.ActivityResult onStartActivity(Intent intent){if(Intent.ACTION_CHOOSER.equals(intent.getAction())){result.set(intent);return new Instrumentation.ActivityResult(Activity.RESULT_CANCELED,null);}return null;}};ins.addMonitor(monitor);return monitor;}
 private Intent sent(AtomicReference<Intent> result)throws Exception{long until=SystemClock.elapsedRealtime()+15000;while(result.get()==null&&SystemClock.elapsedRealtime()<until)Thread.sleep(50);assertNotNull("Android chooser not opened: "+shareDebug.get(),result.get());Intent send=(Intent)result.get().getParcelableExtra(Intent.EXTRA_INTENT);assertNotNull(send);assertEquals(Intent.ACTION_SEND,send.getAction());assertNull(send.getComponent());assertNull(send.getPackage());return send;}
 private void report(String name,JSONObject value)throws Exception{try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"share-shortcuts-"+name+".json"))){out.write(value.toString(2).getBytes("UTF-8"));}complete=true;}
 private void screenshot(String name)throws Exception{Bitmap b=ins.getUiAutomation().takeScreenshot();if(b!=null)try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}finally{b.recycle();}}
 @Test public void nowPlayingSharesSelectedFileAboveFavoriteWithoutMenu()throws Exception{Uri uri=fixture("audio-lossy.mp3",".mp3");activity=ins.startActivitySync(new Intent(c,MainActivity.class).setAction(Intent.ACTION_VIEW).setDataAndType(uri,"audio/mpeg").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_GRANT_READ_URI_PERMISSION));waitFor(()->((Button)field(activity,"share")).isEnabled());ins.waitForIdleSync();AtomicReference<Intent> result=new AtomicReference<>();Instrumentation.ActivityMonitor monitor=chooser(result);try{ins.runOnMainSync(()->{try{Button share=(Button)field(activity,"share"),heart=(Button)field(activity,"favorite");Rect a=new Rect(),b=new Rect(),panel=new Rect();assertTrue(share.getGlobalVisibleRect(a));assertTrue(heart.getGlobalVisibleRect(b));assertTrue(((View)field(activity,"nowPanel")).getGlobalVisibleRect(panel));int target=Ui.dp(c,48);assertTrue(a.width()>=target&&a.height()>=target);assertTrue(b.width()>=target&&b.height()>=target);assertEquals(a.centerX(),b.centerX());assertTrue(a.bottom<=b.top);assertTrue(panel.contains(a)&&panel.contains(b));share.performClick();}catch(Exception e){throw new RuntimeException(e);}});Intent send=sent(result);assertEquals("audio/mpeg",send.getType());assertEquals(uri,send.getParcelableExtra(Intent.EXTRA_STREAM));assertTrue((send.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0);assertEquals(0,send.getFlags()&Intent.FLAG_GRANT_WRITE_URI_PERMISSION);report("now",new JSONObject().put("aboveFavorite",true).put("touchTargetDp",48).put("nativeChooser",true).put("selectedFile",true));screenshot("share-shortcuts-now");}finally{ins.removeMonitor(monitor);}}
 @Test public void recycledMusicRowSharesBoundItemWithoutStartingPlayback()throws Exception{activity=ins.startActivitySync(new Intent(c,DownloadsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Uri a=fixture("audio-lossy.mp3",".mp3"),b=fixture("audio-lossy.mp3",".mp3");MediaItem first=new MediaItem.Builder().setMediaId("first").setUri(a).setMediaMetadata(new MediaMetadata.Builder().setTitle("Primeira").setArtist("Onda").build()).build(),second=new MediaItem.Builder().setMediaId("second").setUri(b).setMediaMetadata(new MediaMetadata.Builder().setTitle("Segunda").setArtist("Onda").build()).build();int[] plays={0};AtomicReference<MediaItem> shared=new AtomicReference<>();ins.runOnMainSync(()->{ListView list=new ListView(activity);LibraryRows rows=new LibraryRows(activity,list,item->plays[0]++,item->{throw new AssertionError("Share opened menu");},shared::set);rows.submit(Arrays.asList(first,second),0);View old=rows.getView(0,null,list),reused=rows.getView(1,old,list);assertSame(old,reused);Button share=button(reused,"Compartilhar música: Segunda");assertNotNull(share);share.performClick();assertSame(second,shared.get());assertEquals(0,plays[0]);((ViewGroup)reused).getChildAt(0).performClick();assertEquals(1,plays[0]);});report("music",new JSONObject().put("recycledRowUsesBoundItem",true).put("shareDoesNotPlay",true).put("rowStillPlays",true));}
 @Test public void recycledVideoRowSharesBoundVideoWithoutSelectingIt()throws Exception{Uri a=fixture("combined.mp4",".mp4"),b=fixture("combined.mp4",".mp4");activity=ins.startActivitySync(new Intent(c,VideoActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));AtomicReference<Intent> result=new AtomicReference<>();Instrumentation.ActivityMonitor monitor=chooser(result);try{ins.runOnMainSync(()->{try{List<VideoStore.Item> visible=(List<VideoStore.Item>)field(activity,"visible");visible.clear();visible.add(new VideoStore.Item(a,"Primeiro vídeo","first.mp4",3000,1000));visible.add(new VideoStore.Item(b,"Segundo vídeo","second.mp4",3000,1000));BaseAdapter adapter=(BaseAdapter)field(activity,"adapter");ListView list=(ListView)field(activity,"videoList");View row=adapter.getView(0,null,list),reused=adapter.getView(1,row,list);assertSame(row,reused);Object before=field(activity,"current");Button share=button(reused,"Compartilhar vídeo: Segundo vídeo");assertNotNull(share);share.performClick();assertSame(before,field(activity,"current"));}catch(Exception e){throw new RuntimeException(e);}});Intent send=sent(result);assertEquals("video/mp4",send.getType());assertEquals(b,send.getParcelableExtra(Intent.EXTRA_STREAM));report("video",new JSONObject().put("recycledRowUsesBoundItem",true).put("shareDoesNotSelectVideo",true).put("nativeChooser",true));}finally{ins.removeMonitor(monitor);}}
 private String js(WebView view,String script)throws Exception{AtomicReference<String> result=new AtomicReference<>();ins.runOnMainSync(()->view.evaluateJavascript(script,result::set));long until=SystemClock.elapsedRealtime()+5000;while(result.get()==null&&SystemClock.elapsedRealtime()<until)Thread.sleep(20);assertNotNull(result.get());return result.get();}
 private WebResourceRequest forged(String url){return new WebResourceRequest(){public Uri getUrl(){return Uri.parse(url);}public boolean isForMainFrame(){return true;}public boolean isRedirect(){return false;}public boolean hasGesture(){return false;}public String getMethod(){return "GET";}public Map<String,String> getRequestHeaders(){return Collections.emptyMap();}};}
 @Test public void youtubeSearchSharesReboundResultOnlyAfterRealUserGesture()throws Exception{activity=ins.startActivitySync(new Intent(c,YouTubeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));WebView[] current={null};String url="https://m.youtube.com/results?search_query=Onda";String html="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'><title>Onda search fixture</title><style>body{margin:0}ytm-video-with-context-renderer{display:block;padding:8px}</style></head><body><ytm-video-with-context-renderer><a href='/watch?v=aqz-KE-bpKQ'>Primeiro vídeo</a></ytm-video-with-context-renderer><ytm-video-with-context-renderer><a id='second' href='/watch?v=56xlZcT--xM'>Segundo vídeo</a></ytm-video-with-context-renderer></body></html>";AtomicReference<Intent> result=new AtomicReference<>();Instrumentation.ActivityMonitor monitor=chooser(result);try{ins.runOnMainSync(()->{try{WebView web=(WebView)field(activity,"web");current[0]=web;web.stopLoading();WebViewClient original=web.getWebViewClient();web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){if(request.isForMainFrame()&&url.equals(request.getUrl().toString()))return new WebResourceResponse("text/html","UTF-8",new ByteArrayInputStream(html.getBytes(java.nio.charset.StandardCharsets.UTF_8)));return original.shouldInterceptRequest(view,request);}@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){if(YouTubeShare.isAction(request.getUrl().toString()))shareDebug.set("gesture="+request.hasGesture()+", mainFrame="+request.isForMainFrame()+", action="+request.getUrl());return original.shouldOverrideUrlLoading(view,request);}@Override public void doUpdateVisitedHistory(WebView view,String target,boolean reload){original.doUpdateVisitedHistory(view,target,reload);}@Override public void onPageFinished(WebView view,String target){original.onPageFinished(view,target);}});Method load=YouTubeActivity.class.getDeclaredMethod("load",String.class);load.setAccessible(true);load.invoke(activity,url);}catch(Exception e){throw new RuntimeException(e);}});WebView web=current[0];boolean ready=false;for(int i=0;i<100;i++){if("2".equals(js(web,"document.querySelectorAll('.onda-share-link').length"))){ready=true;break;}Thread.sleep(50);}assertTrue("Search buttons not inserted",ready);assertEquals("2",js(web,"window.__ondaResultSharing.scan();window.__ondaResultSharing.scan();document.querySelectorAll('.onda-share-link').length"));js(web,"document.querySelectorAll('.onda-share-link')[1].click();");Thread.sleep(300);assertNull("Synthetic page click must not share",result.get());ins.runOnMainSync(()->assertTrue(web.getWebViewClient().shouldOverrideUrlLoading(web,forged("onda-share://youtube/i7j0bw5TonI"))));assertNull(result.get());screenshot("share-shortcuts-youtube");JSONArray point=new JSONArray(js(web,"(function(){document.getElementById('second').href='/watch?v=i7j0bw5TonI&list=PL1234567890';var button=document.querySelectorAll('.onda-share-link')[1],r=button.getBoundingClientRect();return [r.left+r.width/2,r.top+r.height/2,button.getAttribute('href'),innerWidth];})()"));assertEquals("onda-share://youtube/56xlZcT--xM",point.getString(2));int[] location=new int[2];float[] scale={0};ins.runOnMainSync(()->{web.getLocationOnScreen(location);scale[0]=web.getWidth()/(float)point.optDouble(3,1);});float x=location[0]+(float)point.getDouble(0)*scale[0],y=location[1]+(float)point.getDouble(1)*scale[0];long now=SystemClock.uptimeMillis();for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_UP}){MotionEvent event=MotionEvent.obtain(now,SystemClock.uptimeMillis(),action,x,y,0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);assertTrue(ins.getUiAutomation().injectInputEvent(event,true));event.recycle();Thread.sleep(50);}waitFor(()->field(activity,"shareDialog") instanceof AlertDialog&&((AlertDialog)field(activity,"shareDialog")).isShowing());ins.runOnMainSync(()->{try{AlertDialog dialog=(AlertDialog)field(activity,"shareDialog");assertEquals("Vídeo completo (MP4)",dialog.getListView().getAdapter().getItem(0));dialog.getListView().performItemClick(null,1,1);}catch(Exception e){throw new RuntimeException(e);}});Intent send=sent(result);assertEquals("text/plain",send.getType());assertEquals("https://www.youtube.com/watch?v=i7j0bw5TonI",send.getStringExtra(Intent.EXTRA_TEXT));assertNull(send.getParcelableExtra(Intent.EXTRA_STREAM));ins.runOnMainSync(()->assertEquals(url,web.getUrl()));report("youtube",new JSONObject().put("inlineSearchButtons",true).put("reboundVideoLink",true).put("realGestureRequired",true).put("noVideoNavigation",true).put("nativeChooser",true));}finally{ins.removeMonitor(monitor);}}
}
